const originalGetUnavailableDates = App.Http.Booking.getUnavailableDates;
App.Http.Booking.getUnavailableDates = function(providerId, serviceId, selectedDateString, monthChangeStep) {
    if (processingUnavailableDates) { return; }
    if (!providerId || !serviceId) { return; }

    const appointmentId = App.Pages.Booking.manageMode ? vars('appointment_data').id : null;
    const url = App.Utils.Url.siteUrl('booking/get_unavailable_dates');
    const data = {
        provider_id: providerId,
        service_id: serviceId,
        selected_date: encodeURIComponent(selectedDateString),
        csrf_token: vars('csrf_token'),
        manage_mode: Number(App.Pages.Booking.manageMode),
        appointment_id: appointmentId,
    };

    $.ajax({
        url: url,
        type: 'GET',
        data: data,
        dataType: 'json',
    })
    .done((response) => {
        // If the whole month is unavailable, fall back to original logic (complex month search)
        if (response.is_month_unavailable) {
            return originalGetUnavailableDates.call(this, providerId, serviceId, selectedDateString, monthChangeStep);
        }

        // Determine whether we should keep the current date
        let setDateFlag = true; // default to original behavior
        const currentVal = $selectDate.val();
        if (currentVal) {
            const dateFormat = App.Utils.UI.getDateFormat();
            const currentMoment = moment(currentVal, dateFormat);
            if (currentMoment.isValid() && currentMoment.format('YYYY-MM') === selectedDateString.substring(0, 7)) {
                const disabled = response.some(d => d === currentMoment.format('YYYY-MM-DD'));
                if (!disabled) {
                    setDateFlag = false; // keep user's date
                }
            }
        }

        // Apply unavailable dates (grey out) but optionally set the date
        $selectDate.parent().fadeTo(400, 1);
        processingUnavailableDates = true;

        // Grey out unavailable dates
        $selectDate[0]._flatpickr.set(
            'disable',
            response.map((unavailableDate) => new Date(unavailableDate + 'T00:00'))
        );

        if (setDateFlag && !vars('manage_mode')) {
            const selectedDateMoment = moment(selectedDateString);
            const selectedDate = selectedDateMoment.toDate();
            const numberOfDays = selectedDateMoment.daysInMonth();
            $availableHours.text(lang('no_available_hours'));
            for (let i = 1; i <= numberOfDays; i++) {
                const currentDate = new Date(selectedDate.getFullYear(), selectedDate.getMonth(), i);
                if (response.indexOf(moment(currentDate).format('YYYY-MM-DD')) === -1) {
                    App.Utils.UI.setDateTimePickerValue($selectDate, currentDate);
                    App.Http.Booking.getAvailableHours(moment(currentDate).format('YYYY-MM-DD'));
                    break;
                }
            }
        } else if (!setDateFlag && !vars('manage_mode')) {
            // Keep current date, just update available hours for it
            App.Http.Booking.getAvailableHours(moment($selectDate[0]._flatpickr.selectedDates[0]).format('YYYY-MM-DD'));
        }

        processingUnavailableDates = false;
    })
    .fail(() => {
        $selectDate.parent().fadeTo(400, 1);
        processingUnavailableDates = false;
    });
};

